import {validateCourse} from './course-model.js?v=trial-1';

export function assertEditableCourse(course) {
  validateCourse(course);
  // These exact sentinels are generated by payment_public_payload, never editable lessons.
  if (course.lessons.some(lesson =>
    lesson.content === 'Enroll to access this lesson.' ||
    (lesson.question === 'This lesson requires course access.' &&
     lesson.explanation === 'Complete checkout to access this lesson.'))) {
    throw new Error('Locked lesson previews cannot be saved. Reload the full course.');
  }
  return course;
}

export async function loadEditableCourse(client, row) {
  if (!row?.id) throw new Error('Reload the course list before editing.');
  // Independent of checkout. The RPC enforces administrator/enrollment access on the server.
  const content = await client.rpc('payment_get_content', {course_key: row.id});
  if (content.error) throw new Error('Could not load full course content. Editing is blocked; retry after signing in.');
  let payload = content.data;
  if (payload === null) {
    const mode = await client.rpc('payment_course_is_paid', {course_key: row.id});
    if (mode.error || mode.data !== false) {
      throw new Error('Protected course content is unavailable. Editing is blocked.');
    }
    // Free courses have no private payload and retain their ordinary editing behavior.
    payload = row.payload;
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload) ||
      (payload.id !== undefined && payload.id !== row.id)) {
    throw new Error('Invalid course content. Editing is blocked.');
  }
  return assertEditableCourse({...payload, id: row.id});
}
